/* style.css */
h1 {
  color: green;
  font-size: 32px;
}

p {
  color: gray;
}

.card {
  background: white;
  padding: 20px;
}

#header {
  background: black;
}

h1, h2 {
  color: blue;
}

h1 {
  color: #2563eb;
  font-size: 36px;
  font-weight: bold;
  text-align: center;
}

p {
  font-size: 18px;
  line-height: 1.6;
  color: #555;
}

.card {
  width: 300px;
  padding: 20px;
  margin: 30px auto;
  border: 1px solid #ddd;
  border-radius: 12px;
  box-sizing: border-box;
}

.parent {
  position: relative;
}

.badge {
  position: absolute;
  top: 10px;
  right: 10px;
}

.hidden {
  display: none;
}

.container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.item {
  padding: 30px;
  background: #ddd;
}

.container {
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

@media (max-width: 768px) {
  .cards {
    grid-template-columns: 1fr;
  }
}

.button {
  background: blue;
  color: white;
  transition: 0.3s;
}

.button:hover {
  background: darkblue;
  transform: scale(1.05);
}

@keyframes move {
  from { transform: translateX(0); }
  to { transform: translateX(100px); }
}

/* Твой финальный проект */
.container {
  width: 90%;
  max-width: 1200px;
  margin: 0 auto;
}

.navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.courses {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

@media (max-width: 768px) {
  .courses {
    grid-template-columns: 1fr;
  }
}
